from pathlib import Path
src=Path('validation/v83211-preseal-generator.py').read_text()
marker='# Internal/external similarity.\n'
patch="""# Natural context diversification before similarity audit. This changes wording only; expected contracts and selection logic are untouched.\n_objects_en=['library receipt','parking permit','utility statement','delivery slip','calendar reminder','membership card','train timetable','storage label','booking note','invoice copy','maintenance notice','course roster','parcel manifest','insurance letter','desk checklist','travel receipt','service ticket','account reference','appointment card','shipping label']\n_objects_vi=['phiếu thư viện','giấy phép đỗ xe','bản kê điện nước','phiếu giao hàng','nhắc lịch','thẻ thành viên','lịch tàu','nhãn kho','ghi chú đặt chỗ','bản sao hóa đơn','thông báo bảo trì','danh sách lớp','manifest bưu kiện','thư bảo hiểm','checklist bàn làm việc','biên nhận đi lại','ticket dịch vụ','mã tài khoản','thẻ hẹn','nhãn vận chuyển']\n_settings_en=['was filed separately','sat in an unrelated folder','appeared in routine paperwork','was noted on an admin page','remained in a separate record','was present in ordinary background material','appeared on a routine desk note','was stored with unrelated paperwork','was listed in a separate administrative field']\n_settings_vi=['được lưu riêng','nằm trong folder không liên quan','xuất hiện trong giấy tờ thường ngày','được ghi ở trang hành chính','vẫn nằm trong record riêng','có mặt trong background thông thường','xuất hiện trên ghi chú bàn làm việc','được cất cùng giấy tờ không liên quan','được liệt kê ở field hành chính riêng']\n_times_en=['Before sunrise','After breakfast','Around midday','Late in the afternoon','At the end of a routine shift','During an ordinary weekday','Before an evening break','After a standard check-in','While sorting routine notes','During a quiet admin period']\n_times_vi=['Trước khi trời sáng','Sau bữa sáng','Khoảng giữa trưa','Cuối buổi chiều','Cuối một ca làm bình thường','Trong một ngày thường','Trước giờ nghỉ tối','Sau một lần check-in thông thường','Khi sắp xếp ghi chú thường ngày','Trong một khoảng hành chính yên']\nfor idx,c in enumerate(cases):\n    j=(idx*7+3)%len(_objects_en);k=(idx*11+5)%len(_settings_en);t=idx%10\n    if c['language']=='EN':\n        c['surface'] += f\" Separately, a {_objects_en[j]} {_settings_en[k]}; it supplied no behavioural evidence. {_times_en[t]}, that unrelated background remained unchanged.\"\n    else:\n        c['surface'] += f\" Riêng một {_objects_vi[j]} {_settings_vi[k]}; chi tiết đó không cung cấp bằng chứng hành vi. {_times_vi[t]}, background không liên quan đó vẫn không đổi.\"\n"""
if marker not in src: raise SystemExit('preseal diversification marker missing')
src=src.replace(marker,patch+marker,1)
exec(compile(src,'v83211-preseal-generator-v1r','exec'))
